import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G), [ (k,len(v),len(v[0])) for k,v in G.items()])

def transform(grid):
    H=len(grid); W=len(grid[0])
    # wall color: full row/col lines
    wall=max(set(grid[0]))  # risky; find via full rows
    full=[r for r in range(H) if len(set(grid[r]))==1]
    wall=grid[full[0]][0]
    fullc=[c for c in range(W) if all(grid[r][c]==wall for r in range(H))]
    # band row starts
    bands=[r for r in range(H) if r==0 or grid[r-1][0]==wall and any(grid[r][c]!=wall for c in range(W))]
    # simpler: starts = 0 and row after full row
    bands=[0]+[r+1 for r in full if r+1<H]
    regs=[0]+[c+1 for c in fullc if c+1<W]
    bw=len(regs); bh=len(bands)  # region width = ?
    rw=fullc[0] if fullc else W
    rh=full[0] if full else H
    # find shape: colored cells not forming 2x2 block? Find the pattern color != wall and != block colors... 
    # collect cells per (band,reg) region; a region is "block" if exactly a 2x2; "shape" otherwise (nonzero cells not 2x2)
    shape=None
    for r0 in bands:
        for c0 in regs:
            cells=[(r-r0,c-c0) for r in range(r0,r0+rh) for c in range(c0,c0+rw) if grid[r][c]!=0 and grid[r][c]!=wall]
            if cells and not (len(cells)==4 and len({p[0] for p in cells})==2 and len({p[1] for p in cells})==2):
                shape={(p[0],p[1]):grid[r0+p[0]][c0+p[1]] for p in cells}
    out=[row[:] for row in grid]
    for i,r0 in enumerate(bands):
        # band color: the block color in this band (any nonzero non-wall cell)
        color=None
        for c0 in regs:
            for r in range(r0,r0+rh):
                for c in range(c0,c0+rw):
                    if grid[r][c] not in (0,wall): color=grid[r][c]; break
        for c0 in regs:
            for (dr,dc),v in shape.items():
                out[r0+dr][c0+dc]=color
    return out

